examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true })
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }) {
        MonarchAiSourcePreview(
            source = MonarchAiSourcePart(
                id = {{source.id}},
                title = {{source.title}},
                url = {{source.url}},
                kind = MonarchAiSourceKind.{{source.kind|pascal}},
                product = {{source.product}},
            ),
            quote = {{quote}},
            content = {{content}},
            onClose = { open = false },
        )
    }
}

examples.code:
MonarchButton(text = "Preview source", onClick = { open = true })
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }) {
        MonarchAiSourcePreview(
            source = MonarchAiSourcePart(
                id = "s1",
                title = "Team handbook",
                url = "https://example.com/handbook",
                kind = MonarchAiSourceKind.Doc,
                product = "Docs",
            ),
            quote = "Requests are answered within two working days.",
            content = "Welcome to the team. This handbook explains how we work together.\n\nRequests are answered within two working days. Urgent issues go to the on-call queue, which answers within two hours.\n\nEvery request gets an owner. The owner keeps the requester up to date until it is closed.",
            onClose = { open = false },
        )
    }
}
